(window.SITE_PRS=window.SITE_PRS||{})["haacked"]=[{"id":"ws1","title":"Query engine (HogQL) · flags","area":"Query engine (HogQL)","agg":{"prs_n":158,"deepread_n":15,"tier_counts":{"major":45,"substantive":80,"routine":31,"trivial":2},"points_sum":775.07,"L_mean":1.33,"Q_mean":1.47,"span_days":86,"lines":68493},"prs":[{"number":77598,"tier":"major","P":null,"summary":"Renaming a feature flag silently disabled session replay for gated teams; this relinks stored keys on rename and backfills affected projects."},{"number":78070,"tier":"substantive","P":null,"summary":"Adds Redis read-repair on S3 hit in HyperCacheReader to stop sustained S3 reads for cold keys, gated by config."},{"number":79218,"tier":"routine","P":null,"summary":"Adds an internal counter metric and alert to detect hypercache verification runs that wind down early, improving observability for the feature-flags team."},{"number":79288,"tier":"substantive","P":null,"summary":"Feature flag usage charts render inline as unsaved queries, stopping auto-created dashboards and insights that cluttered users' lists."},{"number":79906,"tier":"substantive","P":null,"summary":"Adds ?tab= deep-linking to the feature flag detail page so users can share and reload links to specific tabs like usage or schedule."},{"number":80022,"tier":"substantive","P":null,"summary":"Pre-seeds hypercache verification task metric series on every Celery worker so the flags on-call alert can't silently go quiet when a task dies."},{"number":80029,"tier":"substantive","P":null,"summary":"Adds a management command to safely soft-delete auto-generated feature flag usage insights, keeping any that show signs of real use."},{"number":80814,"tier":"routine","P":3.65,"summary":"Replaces JSON.stringify with the existing BigInt-safe stringifyWithBigInts helper in the feature flag copy-failure toast so BigInt payloads no longer throw and the error reason reaches the user, with a regression test."},{"number":80995,"tier":"routine","P":null,"summary":"Adds metrics and canonical-log signal counting requests whose supplied $geoip_* values differ from the lookup, to size a future precedence flip."},{"number":80998,"tier":"major","P":null,"summary":"Bulk delete now refuses flags gating session replay, preventing silent loss of a team's recording data."},{"number":81020,"tier":"substantive","P":null,"summary":"Adds a staff-tools override for a single team's feature flag limit, so support can raise caps without a fleet-wide redeploy."},{"number":81463,"tier":"substantive","P":null,"summary":"Blanks filters for disabled/deleted flags in both Python and Rust cache writers to stop etag flips and needless full cache reloads."},{"number":81575,"tier":"major","P":null,"summary":"Fixes flag renames/deletes silently breaking session replay trigger groups, preventing loss of recordings for affected teams."},{"number":82117,"tier":"substantive","P":null,"summary":"Both flag-cache writers now drop unreferenced inactive flags, shrinking Redis/S3/memory while preserving dependency-referenced ones."},{"number":82119,"tier":"routine","P":null,"summary":"Adds a guard so two flag dashboard endpoints return 400 for soft-deleted flags instead of regenerating useless insights."},{"number":82180,"tier":"routine","P":null,"summary":"Removes a dead legacy Redis cache writer that ran on every flag save/delete, cutting a DB query and two Redis writes per mutation."},{"number":82239,"tier":"routine","P":null,"summary":"Extends the flag-usage-insight cleanup command to sweep soft-deleted flags' dashboards by default and adds subscription-aware keep checks."},{"number":83382,"tier":"substantive","P":null,"summary":"Switches flag_evaluations typed columns from MATERIALIZED to DEFAULT to unblock future property-rewrite deletion; no behavior change yet."},{"number":85528,"tier":"substantive","P":null,"summary":"Mirrors posthog_featureflag into the ClickHouse mirror with an hourly sync plus per-hour backfill asset, and redacts encrypted-payload ciphertext before mirroring."},{"number":86720,"tier":"major","P":null,"summary":"Fixes flag renames silently disabling session replay for linked teams by relinking under muted signals and handling tombstoned keys."},{"number":87131,"tier":"major","P":null,"summary":"Fixes silent failures in hypercache verification by implementing controlled shutdown logic and adjusting task scheduling to prevent Celery from killing workers mid-batch."},{"number":89733,"tier":"major","P":5.92,"summary":"Extends the replay linked-flag repair management command to also find and fix stale flag keys inside session replay trigger groups, with id-priority resolution, index-based selection and locked writes, so teams whose recording gate silently broke start recording again."},{"number":90613,"tier":"substantive","P":null,"summary":"Deprecates legacy feature flag usage dashboard API endpoints with Sunset headers, telemetry, and OpenAPI deprecation to signal migration to API consumers."},{"number":91199,"tier":"routine","P":null,"summary":"Removes the fully-rolled-out starts-with/ends-with flag gate from the property filter operator dropdown, dropping a needless kea subscription and stale tests."},{"number":91206,"tier":"routine","P":null,"summary":"Deduplicates taxonomic filter context-filter helpers into shared functions and adds tests covering the menu's pinned filter, with no behavior change."},{"number":91208,"tier":"routine","P":null,"summary":"Removes the A/B test results replay template and its flag variable type ahead of a data move that would break it."},{"number":91412,"tier":"substantive","P":null,"summary":"Fixes the taxonomic filter so excluded events can no longer be selected via search, pins, or autocomplete shortcuts in transformation filters."},{"number":91418,"tier":"major","P":null,"summary":"Fixes negative property operators dropping rows with missing properties, correcting wrong query results across insights, cohorts, error tracking, replay and flags."},{"number":92740,"tier":"substantive","P":null,"summary":"Re-enables the taxonomy drift CI check and regenerates the JSON, restoring the missing $mcp_scope_preset property in frontend filter lists."},{"number":92840,"tier":"substantive","P":null,"summary":"Hides $feature_flag_called from event pickers behind a flag, with opt-in for live-data and experiment pickers."},{"number":92994,"tier":"substantive","P":null,"summary":"Adds a catalog-walking test and docs enforcing that every table with property blob columns has a matching access-control dispatch branch."},{"number":92995,"tier":"substantive","P":null,"summary":"Adds a flag_evaluations HogQL table behind an org feature flag, letting customers query flag evaluation data with property access control."},{"number":95520,"tier":"routine","P":null,"summary":"Makes the flags rate-limit replenishment test deterministic by injecting a clock, with no user-visible behavior change."},{"number":95693,"tier":"major","P":null,"summary":"Flag-evaluation rows now omit person properties so property-removal requests are honored, closing a privacy retention gap in ingestion."},{"number":95702,"tier":"routine","P":null,"summary":"Consolidates feature-flag migration test scenarios into shared checks to speed up focused migration test runs; test-only, no product impact."},{"number":97009,"tier":"substantive","P":null,"summary":"Fixes a deletion-job crash on person-property requests by narrowing the flag_evaluations gate to skip its dropped person_properties column."},{"number":97027,"tier":"routine","P":null,"summary":"Drops unused person/group property columns from the flag_evaluations schema template so dev, local and CI match prod."},{"number":97080,"tier":"substantive","P":null,"summary":"Splits the ETag metric into redis_missing vs redis_error and adds a runbook so on-call can tell an empty cache tier from a broken Redis."},{"number":98620,"tier":"routine","P":null,"summary":"Adds a Python test guarding the invariant that 'group' is the only non-person-aggregated property type, preventing silent drift with a TypeScript merge helper."},{"number":98802,"tier":"major","P":null,"summary":"Ensures person deletions also squash flag_evaluations person_id after merges, so queryable flag-evaluation history no longer survives deletion."},{"number":98865,"tier":"substantive","P":null,"summary":"Adds CI invariants tying person-deletion registration to squash targets and a MutationNotFound retry, preventing future person-id data leaks after merges."},{"number":98888,"tier":"major","P":null,"summary":"Enables feature flag usage charts to read from the new flag_evaluations table and fixes critical query compilation errors."},{"number":98900,"tier":"major","P":null,"summary":"Resolves flag_evaluations.person_id through person merges so HogQL counts merged persons once instead of double-counting flag evaluations."},{"number":101211,"tier":"routine","P":null,"summary":"Cohort edit page collapses the 'Used in' dependency list into a compact expandable summary line so the criteria builder stays above the fold."},{"number":101285,"tier":"substantive","P":null,"summary":"Static cohorts now surface failed population with an error banner and reason instead of an empty persons table, plus new ClickHouse byte-limit error mapping."},{"number":101307,"tier":"substantive","P":null,"summary":"Adds sampling to the feature-flag release-condition size count so large projects get an audience estimate instead of a memory-limit error."},{"number":104868,"tier":"routine","P":null,"summary":"Documents the flag_evaluations person_id join limitation in HogQL AI prompts, giving the assistant working join alternatives."},{"number":105446,"tier":"substantive","P":null,"summary":"Adds an organization-level flag_evaluations mode so the Usage tab, HogQL catalog and Node ingestion read one shared value; phase 1 only."},{"number":106185,"tier":"routine","P":null,"summary":"Adds an unused flag_evaluations_mode column to TeamFeatureFlagsConfig as a deploy-ordering prerequisite for a stacked feature-flags PR."},{"number":106290,"tier":"substantive","P":2.7,"summary":"Adds a staff-only API endpoint and UI modal to preview and apply flag evaluations mode changes for the organizations of selected teams, reusing shared helpers with the existing management command."},{"number":106364,"tier":"substantive","P":null,"summary":"Gives flag-definition 304 revalidation polls a separate rate-limit budget so cheap polls no longer exhaust the full-response limit and cause 429s."},{"number":107956,"tier":"substantive","P":null,"summary":"Adds a new organization-level feature flags config table to unblock the per-organization flag evaluations rollout."},{"number":108014,"tier":"major","P":null,"summary":"Fixes feature-flags DB timeout ordering so stalled persons replicas no longer cause reconnect storms on the core /flags endpoint."},{"number":108017,"tier":"substantive","P":null,"summary":"Bounds persons DB calls in /flags with a deadline so SDKs get 200 with errorsWhileComputingFlags instead of 503 for all flags when persons DB stalls."},{"number":108484,"tier":"substantive","P":null,"summary":"Adds a Dagster job to backfill flag_evaluations from events, unblocking the flag-usage reader migration without waiting for dual-write history."},{"number":108772,"tier":"major","P":16.0,"summary":"Applies the persons DB deadline to the group type mapping lookup by running the coalesced moka fetch in a detached task with a 5s cap, so a frozen persons DB yields a 200 instead of a 503 for every flag, with metrics, docs, and regression tests."},{"number":109565,"tier":"major","P":null,"summary":"Feature-flag evaluation now marks flags as failed when a dependency flag fails, preventing SDKs from receiving silently wrong values."},{"number":109587,"tier":"routine","P":null,"summary":"Makes two flaky Tokio monitor delta tests deterministic by running them on a current-thread runtime instead of multi-thread."},{"number":109599,"tier":"substantive","P":null,"summary":"Fixes the flag_evaluations backfill so it stops copying days whose TTL has already expired, preventing dropped rows and wasted runs."},{"number":109631,"tier":"routine","P":null,"summary":"Merges JSON-null, missing and empty flag responses into one 'None (i.e. no value)' bucket in the flag Usage tab charts and table."},{"number":109636,"tier":"major","P":null,"summary":"Fixes dependent feature flags returning wrong values on the Postgres fallback path and removes a 500 for cyclic-dependency teams."},{"number":110148,"tier":"substantive","P":null,"summary":"Feature flags Projects tab now counts evaluations from flag_evaluations for FLAG_EVALUATIONS_ONLY orgs, avoiding zero counts."},{"number":110149,"tier":"substantive","P":12.13,"summary":"Routes the events list filtered to exactly $feature_flag_called to posthog.flag_evaluations for organizations on FLAG_EVALUATIONS_ONLY mode, adding person/group lazy joins, a flag_key predicate, and a dismissible Activity-page note, so the Activity page and flag Usage Log keep showing flag calls once that mode becomes the default."},{"number":110150,"tier":"substantive","P":null,"summary":"Adds a setting to read last_called_at sync from flag_evaluations, fixing stale-flag detection for orgs storing calls only there."},{"number":110250,"tier":"substantive","P":null,"summary":"Optimizes flag-call person name lookup to only the page's rows, avoiding full-team person dedup and unblocking FLAG_EVALUATIONS_ONLY mode."},{"number":110254,"tier":"major","P":null,"summary":"Stops writing $feature_flag_called to events for FLAG_EVALUATIONS_ONLY orgs, routing them to flag_evaluations and unblocking new-org rollout."},{"number":110338,"tier":"substantive","P":null,"summary":"Fixes the flag_evaluations backfill to wait for ClickHouse part moves instead of prematurely stopping shards, unblocking full prod runs."},{"number":110392,"tier":"substantive","P":null,"summary":"Adds an opt-in HogQL personIdPushdown modifier that restricts joined persons lookups to reachable persons, cutting query cost for person-property filters."},{"number":110487,"tier":"substantive","P":null,"summary":"Enables personIdPushdown for the flag-calls list query, preventing memory-limit failures for teams with many persons."},{"number":111071,"tier":"substantive","P":null,"summary":"Backfill lag check now measures from Kafka message time instead of inserted_at, preventing duplicate row copies once the MV change lands."},{"number":111090,"tier":"trivial","P":1.66,"summary":"A text-only PR that rewrites staff-facing help text, docstrings, comments and regenerated OpenAPI types to correctly describe which readers move to flag_evaluations in modes 1 and 2, fixing misleading documentation without changing any behavior."},{"number":111128,"tier":"major","P":null,"summary":"Enables flag-call forking on all ingestion lanes and adds a TTL guard preventing flag calls from being dropped from events."},{"number":111129,"tier":"major","P":null,"summary":"Prevents duplicate flag_evaluations rows in the backfill by skipping events whose fork row may still be in Kafka."},{"number":111148,"tier":"substantive","P":null,"summary":"Event pickers now hide $feature_flag_called for orgs on flag_evaluations_mode 1/2, supporting the flag evaluations rollout."},{"number":111169,"tier":"major","P":null,"summary":"Fixes backfill cleanup DELETE to match only copied rows, preventing accidental deletion of real flag evaluation data."},{"number":112066,"tier":"substantive","P":null,"summary":"Extends property-removal deletion sweeps to the flag_evaluations table so stuck deletion requests can complete instead of waiting ~120 days for TTL."},{"number":112117,"tier":"substantive","P":null,"summary":"Makes mode 1 flag views (Usage log, Projects counts, Activity list) read flag_evaluations, aligning them with mode 2 for a safer migration."},{"number":112264,"tier":"major","P":null,"summary":"Stamps flag_evaluations inserted_at with insert time (now64()) instead of Kafka time, fixing data-correctness window bugs in deletion sweeps and checkpoints."},{"number":112836,"tier":"major","P":null,"summary":"Fixes person-deletion cutoff losing sub-second precision, which left rows behind while marking deletion requests verified."},{"number":112933,"tier":"substantive","P":null,"summary":"Group-targeted flags now return failed:true instead of false when the group type lookup fails, preventing SDKs from caching wrong values."},{"number":112935,"tier":"substantive","P":null,"summary":"Fixes personhog-replica hash key override SQL to ignore cookieless sentinels, preventing wrong experiment variants before the feature-flags migration."},{"number":112987,"tier":"routine","P":null,"summary":"Fixes overlapping step and marker labels on the feature flag schedule timeline so labels no longer draw over each other."},{"number":112991,"tier":"substantive","P":null,"summary":"Lets insights (trends, funnels, retention, etc.) chart flag calls from the flag_evaluations table for orgs on that mode."},{"number":113480,"tier":"major","P":7.29,"summary":"Fixes person-merge SQL in both the nodejs repository and the personhog-identity saga so a source's real feature-flag hash key replaces a target's cookieless sentinel instead of being silently deleted, preserving correct experiment variant assignment."},{"number":113495,"tier":"substantive","P":null,"summary":"Hardens feature flag validation so release conditions on deleted cohorts are rejected across save, enable, restore and undo paths, preventing silent flag evaluation failures."},{"number":113497,"tier":"routine","P":null,"summary":"Adds a 2s lock_timeout and IMMEDIATE constraints to personhog replica hash key override upserts to fail fast behind locked person rows."},{"number":113500,"tier":"substantive","P":null,"summary":"Fixes a bug in the feature flags testing tab where failed flag dependencies were reported incorrectly, improving user clarity and debugging experience."},{"number":113502,"tier":"substantive","P":null,"summary":"Caps the persons DB deadline at the request timeout so /flags returns 200 with only person flags failed instead of 503 during DB stalls."},{"number":113594,"tier":"routine","P":null,"summary":"personhog-replica now imports the shared cookieless sentinel from personhog-common instead of keeping its own copy, preventing cross-service divergence."},{"number":113666,"tier":"substantive","P":null,"summary":"Bounds the personhog replica hash-key-override insert with a 2s statement timeout so callers get the replica's error before their deadline."},{"number":113691,"tier":"substantive","P":null,"summary":"Adds warning banners to insights, dashboards, actions and cohorts that read $feature_flag_called, guiding customers to rebuild when moving to flag_evaluations_mode 2."},{"number":113692,"tier":"major","P":null,"summary":"Flag-based cohort runs now fail on per-person evaluation errors instead of silently omitting people, fixing wrong cohort data and partial broadcasts."},{"number":114059,"tier":"substantive","P":null,"summary":"Adds a SQL editor warning when queries read $feature_flag_called from events, ahead of the event's move to flag_evaluations."},{"number":114061,"tier":"substantive","P":null,"summary":"Blocks new action steps and cohort criteria on $feature_flag_called for orgs reading flag_evaluations, with API errors and UI move warnings."},{"number":114063,"tier":"routine","P":null,"summary":"Removes deprecated feature flag usage dashboard endpoints (now 404) and cleans up related frontend calls, serializers, and tests."},{"number":114082,"tier":"substantive","P":null,"summary":"Adds the persons DB deadline to batch flag evaluation so static cohort creation no longer stalls ~6 minutes on unresponsive queries."},{"number":114085,"tier":"routine","P":null,"summary":"Moves the feature flag usage dashboard builder out of production code into a test fixture, with no user-visible change."},{"number":114172,"tier":"substantive","P":null,"summary":"Adds a flag-gated notice about the 'Feature flag called' event moving to flag_evaluations, shown in four UI locations, and trims the event description."},{"number":114183,"tier":"routine","P":null,"summary":"Fixes the property info popover so it stays open and its description links are clickable, opening docs in a new tab."},{"number":114210,"tier":"substantive","P":null,"summary":"Fixes flag-evaluation event links without an event name so they resolve the flag call instead of opening an empty events page."},{"number":114251,"tier":"routine","P":2.19,"summary":"Adds a conditional \"Learn more\" link to the hidden-event explanation in both the legacy and rebuilt taxonomic filter pickers, extracting the copy into a shared HiddenEventExplanation component with targeted tests."},{"number":114261,"tier":"substantive","P":null,"summary":"Adds person_properties, person_created_at and person_mode columns to flag_evaluations to enable person-filtered flag insights without joins."},{"number":114264,"tier":"substantive","P":null,"summary":"Adds an optional url field to HogQLNotice and renders a 'Learn more' link in the SQL editor's flag-move warning."},{"number":114271,"tier":"major","P":7.82,"summary":"Immediate event-removal requests without a HogQL predicate now sweep and verify the flag_evaluations table (previously always skipped), closing a data-deletion correctness gap where deleted $feature_flag_called copies lingered for ~120 days while the request reported success."},{"number":114276,"tier":"major","P":9.62,"summary":"Removes the `stores_person_properties` flag so property-removal requests now count, rewrite and verify `person_properties` on `flag_evaluations` like on `events`, closing a data-deletion blind spot, with an empty-string guard around the JSONDropKeysPool UDF."},{"number":114745,"tier":"major","P":null,"summary":"Fixes deferred event deletion so flag_evaluations rows tied to matching events are deleted, unblocking predicate-based deletion requests for teams using feature flags."},{"number":114757,"tier":"substantive","P":null,"summary":"Adds an opt-in HogQL modifier rewriting negated person filters into a persons NOT IN subquery, avoiding a full persons join and speeding up joined-mode insights."},{"number":114775,"tier":"substantive","P":null,"summary":"JSONDropKeys UDF now returns empty string for empty input, so HogQL property-masking queries no longer fail on rows with empty JSON columns."},{"number":116519,"tier":"major","P":null,"summary":"Changes flag_evaluations table engine to ReplacingMergeTree to deduplicate repeated flag calls, fixing overcounts for affected teams."},{"number":116540,"tier":"major","P":null,"summary":"Backfill now copies person_properties, person_created_at and person_mode into flag_evaluations, fixing wrong person data in backfilled flag-evaluation history."},{"number":116549,"tier":"substantive","P":null,"summary":"Personhog now classifies Postgres statement/lock timeouts as DEADLINE_EXCEEDED with distinct metric labels, letting operators alert and callers distinguish timeouts."},{"number":116555,"tier":"substantive","P":null,"summary":"Fixes HogQL printer to guard JSONDropKeys on empty String JSON columns, preventing queries with restricted-property masking from failing on legacy event rows."},{"number":116693,"tier":"substantive","P":null,"summary":"Enables person, group, element and session test-account filters on flag_evaluations insights, unblocking flag_evaluations-only mode for orgs."},{"number":116704,"tier":"substantive","P":null,"summary":"Fixes personhog router so Python gRPC clients receive real error statuses instead of UNKNOWN, correcting retry behavior."},{"number":117127,"tier":"substantive","P":null,"summary":"Geoip subdivision properties are now treated as instantly available in flag release conditions, removing the first-page-load warning and the Rust per-team exclusion list."},{"number":117275,"tier":"substantive","P":null,"summary":"create_group now returns the existing group on a duplicate key instead of a 500, fixing a concurrent-create race in personhog-replica."},{"number":117390,"tier":"major","P":null,"summary":"Adds materialized property-group map columns to flag_evaluations so HogQL property filters match correctly instead of reading raw JSON."},{"number":117391,"tier":"major","P":null,"summary":"Hardens team API writes to replay gate columns, fixing stale flag keys and access-control gaps that stopped session recording and leaked flag keys."},{"number":117395,"tier":"major","P":16.0,"summary":"This PR lets deferred HogQL-predicate deletion requests reach flag_evaluations rows that have no events copy by compiling the predicate against posthog.flag_evaluations with guards against joins, element columns, property-group maps and materialized columns, fixing a compliance gap for mode-2 orgs."},{"number":117397,"tier":"major","P":null,"summary":"Fixes SQL insights by allowing dashboard filters to correctly apply to the flag_evaluations table, resolving a critical query failure."},{"number":117421,"tier":"substantive","P":null,"summary":"Lifecycle insights on flag calls now exclude personless calls, matching events lifecycle counts."},{"number":117930,"tier":"major","P":null,"summary":"Fixes flag_evaluations query results so null/missing response sentinels read as NULL, matching events and correcting flag calls charts and SQL."},{"number":118050,"tier":"major","P":null,"summary":"Fixes HogQL multi-value negative filters (not_in, not_icontains_multi) that wrongly returned rows they should exclude, correcting query results."},{"number":118126,"tier":"substantive","P":null,"summary":"Fixes HogQL warehouse filters so between/not_between work and whole-list operators emit a single comparison instead of failing or splitting per value."},{"number":118127,"tier":"major","P":5.92,"summary":"Fixes lifecycle insights on flag calls so a person/group is marked new based on their actual creation time (person.created_at or group_N.created_at) rather than the first flag call timestamp, aligning flag_evaluations results with events and adding frontend retargeting plus regression tests."},{"number":118157,"tier":"substantive","P":null,"summary":"Enables HogQL to read pre-computed property-group maps on flag_evaluations, letting bloom-filter indexes prune granules and speeding up flag-calls insights."},{"number":118224,"tier":"substantive","P":null,"summary":"Reserves the exact variant key \"null\" for new feature flags to prevent its traffic being miscounted as no-value in flag_evaluations analytics."},{"number":118241,"tier":"major","P":null,"summary":"Fixes logs negative resource-attribute filters that returned inverted or wrong results for not_icontains_multi and semver_neq operators, correcting query correctness."},{"number":118242,"tier":"substantive","P":null,"summary":"Flag calls insights now retain test-account and global filters across trends, funnels, retention, stickiness and lifecycle, and dashboard tiles apply property filters."},{"number":118803,"tier":"substantive","P":null,"summary":"Rejects empty variant keys on new feature-flag writes, preventing ambiguous '' values that misreport variant traffic as no response."},{"number":118839,"tier":"substantive","P":4.49,"summary":"This PR makes the lifecycle insight on flag calls filter personless rows via the materialized person_mode column instead of parsing the properties JSON of every row, keeping identical results while cutting per-row work."},{"number":118840,"tier":"substantive","P":null,"summary":"Adds in-app notices and a management command alerting teams whose active flags target deleted cohorts, with a new notification type and recipient checks."},{"number":119792,"tier":"substantive","P":null,"summary":"Feature flag UI now flags release conditions on deleted/missing cohorts, warning users and disabling enable/unarchive/restore until fixed."},{"number":119898,"tier":"major","P":null,"summary":"Adds a one-off job to repair person_id on imported flag_evaluations rows, fixing overcounted unique persons and dropped cohort filters."},{"number":120789,"tier":"trivial","P":1.66,"summary":"A docs-only README edit that adds the Dagster+ org and prod-us/prod-eu deployment URLs and renames \"Dagster Cloud\" to \"Dagster+\", saving engineers a URL search."},{"number":121651,"tier":"substantive","P":null,"summary":"Lowered the flag_evaluations last_called_at sync buffer from 900s to 360s and disabled stale-replica fallback, cutting lag and preventing lost calls."},{"number":121667,"tier":"major","P":null,"summary":"Fallback /flags responses now set errorsWhileComputingFlags so SDKs keep stored flag values instead of dropping them during outages."},{"number":121672,"tier":"routine","P":null,"summary":"Adds a timestamp gauge for the feature flag last_called_at sync checkpoint so monitoring can compute checkpoint age reliably."},{"number":121699,"tier":"substantive","P":null,"summary":"Fixes Celery PushGatewayTask to push duration and success=0 on failure so success-rate dashboards and alerts reflect failed runs."},{"number":121713,"tier":"substantive","P":null,"summary":"Re-enables $feature_flag_called in destination and workflow event pickers for all flag evaluation modes, unblocking teams that previously could not select it."},{"number":121753,"tier":"routine","P":null,"summary":"Feature flag metrics tests now reuse PushGatewayTaskTestMixin instead of a duplicated mock; test-only, no behavior change."},{"number":121754,"tier":"routine","P":null,"summary":"Adds malformed v1 groups rows to the flags cache parity fixture and aligns the Python test harness, improving test coverage only."},{"number":121813,"tier":"major","P":null,"summary":"Correctly calculates volume estimates in Workflows and Destinations for feature flag mode 2 by querying the dedicated flag evaluations table."},{"number":122238,"tier":"routine","P":null,"summary":"Removes the dead flag-evaluations-hogql-table feature-flag gate so HogQL visibility depends only on the organization's flag_evaluations mode, with no behavior change."},{"number":122399,"tier":"substantive","P":null,"summary":"Avoids a slow persons join when counting mode-2 flag calls, speeding up destination/workflow volume estimates and preventing OOM."},{"number":124397,"tier":"major","P":16.0,"summary":"HogQL now transparently rewrites queries that ask `events` for `$feature_flag_called` to read `posthog.flag_evaluations` (with extensive shape/binding guards and mode 1 vs mode 2 handling), so existing saved insights, cohorts, trends and actions keep returning flag calls after an organization switches away from writing them to `events`."},{"number":124485,"tier":"major","P":null,"summary":"Raises flag_evaluations ClickHouse TTL to 92 days so 90-day flag insights don't miss the earliest day due to timezone boundaries."},{"number":124555,"tier":"routine","P":null,"summary":"Aligns Python flag_evaluations TTL/retention constants with the already-applied 92-day migration; no user-visible change."},{"number":124556,"tier":"substantive","P":null,"summary":"Fixes a false flag-call retention notice shown to non-UTC teams by comparing the range cutoff in the team timezone."},{"number":125070,"tier":"substantive","P":null,"summary":"Fixes HogQL flag_evaluations array reads and lazy session joins so previously failing feature-flag and session queries now run correctly."},{"number":125115,"tier":"major","P":null,"summary":"Fixes flag-call queries on posthog.events silently returning stale events data in flag_evaluations mode 2, a query-correctness bug."},{"number":125172,"tier":"substantive","P":null,"summary":"Adds a warning when lifecycle insights over flag calls read before the 90-day retention, preventing misleading first-period results."},{"number":125267,"tier":"major","P":null,"summary":"Fixes HogQL flag-call rewrite so funnels, trends, retention and experiments no longer silently miss flag calls, restoring correct insight results."},{"number":125649,"tier":"major","P":null,"summary":"Fixes HogQL flag-call scans that silently returned only pre-migration events after mode 2 swap, now reading flag_evaluations or erroring."},{"number":125750,"tier":"substantive","P":null,"summary":"Fixes saved SQL views so flag calls on mode 2 read from flag_evaluations instead of erroring or returning stale results."},{"number":126076,"tier":"major","P":null,"summary":"Removes a rollout flag so HogQL always reads flag calls from flag_evaluations by org mode, fixing queries that missed every flag call."},{"number":126896,"tier":"routine","P":null,"summary":"Pins fixed dates in two DST-sensitive backend tests to stop AmbiguousTimeError flakiness during the fall-back hour."},{"number":126899,"tier":"substantive","P":null,"summary":"Fixes DST-related exceptions in HogQL's is_integer_timezone that broke queries during clock-change hours for DST timezones."}]},{"id":"ws2","title":"Django platform (API/models/auth) · cohorts","area":"Django platform (API/models/auth)","agg":{"prs_n":27,"deepread_n":1,"tier_counts":{"substantive":20,"trivial":1,"routine":4,"major":2},"points_sum":110.62,"L_mean":3,"Q_mean":1,"span_days":83,"lines":62299},"prs":[{"number":80994,"tier":"substantive","P":null,"summary":"Mirrors events schema in flag_evaluations ClickHouse table family, adding materialized columns and migration to prepare for moving flag evaluation events off events table."},{"number":82056,"tier":"substantive","P":9.62,"summary":"Introduces a central deletion-target registry so person/team/queued-uuid/event-removal sweeps reach flag_evaluations (and other personal-data tables), adds loud refusals for unsweepable property/HogQL paths, and fixes a ClickHouse mutation-dedup SQL injection."},{"number":89779,"tier":"trivial","P":null,"summary":"Reworded flag property `type`/`group_type_index` help text to mention group targeting, regenerating API clients and MCP schemas."},{"number":91201,"tier":"substantive","P":null,"summary":"Seeds new teams' internal/test-user cohort with an exact ends_with domain match, fixing over-matching that silently dropped real customers from insights and experiments."},{"number":92959,"tier":"routine","P":null,"summary":"Adds a docs-only runbook for manually running the flag_evaluations parity spot check via Metabase."},{"number":104617,"tier":"major","P":null,"summary":"Adds object-level permission check to the flag_value.values endpoint, closing an RBAC bypass that leaked variant keys of restricted flags in production."},{"number":105623,"tier":"substantive","P":null,"summary":"Fixes a weak signal receiver that never ran in production, making team extension row creation opt-in and adding a flags config default."},{"number":113688,"tier":"substantive","P":null,"summary":"Cohort API now rejects saves referencing deleted/missing cohorts and blocks deleting cohorts used via groups, preventing broken feature-flag evaluations."},{"number":116532,"tier":"substantive","P":null,"summary":"Fixes stuck static cohorts (flag/CSV) that show 'calculating' forever after a killed worker, resetting them to failed and stopping runaway polling."},{"number":116658,"tier":"routine","P":null,"summary":"Personhog RetryInterceptor now skips fast in-process retry for DB timeouts marked with x-db-timeout metadata, aligning with an upcoming server change."},{"number":116705,"tier":"substantive","P":null,"summary":"Fix the personhog Python client's retry interceptor to read gRPC status from the returned outcome so transient errors are actually retried."},{"number":117314,"tier":"substantive","P":null,"summary":"RemoteConfig now drops malformed replay trigger groups and reports errors, preventing SDKs from receiving no config or crashing on bad data."},{"number":117368,"tier":"substantive","P":null,"summary":"Team/Project APIs now store trigger-group flag ids as ints so the flag-delete guard matches, preventing session replay from being silently disabled."},{"number":117385,"tier":"substantive","P":null,"summary":"Static cohort CSV uploads now accept the `Person.id` header written by PostHog exports, unblocking a previously failing user workflow."},{"number":118739,"tier":"routine","P":null,"summary":"Makes three dashboard snapshot tests fill Django/lru caches before query capture, eliminating order-dependent snapshot churn in unrelated PRs."},{"number":118777,"tier":"substantive","P":null,"summary":"Fixes per-process caching of Team configs so settings changes apply on the next request and stale objects no longer overwrite fields."},{"number":118819,"tier":"routine","P":null,"summary":"Fixes concurrent group creation race to return 400 instead of 500, with fake client and test updates."},{"number":119084,"tier":"substantive","P":null,"summary":"Eliminates duplicate tile prefetching so dashboard GET/PATCH/stream/run-insights requests run fewer Postgres queries."},{"number":119085,"tier":"substantive","P":null,"summary":"Replaces a broken custom cached_property stand-in with functools.cached_property across query runners, fixing cross-instance cache eviction and stale-value bugs."},{"number":119735,"tier":"substantive","P":null,"summary":"Fixes Postgres query-snapshot test helper so N+1 snapshots capture all queries, restoring effective N+1 guards across the repo."},{"number":119939,"tier":"substantive","P":null,"summary":"Fixes session replay trigger groups storing flag objects so they match and record, gated behind a rollout flag."},{"number":121826,"tier":"major","P":null,"summary":"Packs the shuffler's input topic into source_partition so a second shuffler can safely run on realtime_only_events_json, fixing realtime cohorts that stopped updating."},{"number":122179,"tier":"substantive","P":null,"summary":"Rewrites the groups list query to dedup in two phases, fixing out-of-memory failures so group search works on large projects."},{"number":124498,"tier":"substantive","P":null,"summary":"Restores 'Feature flag called' cohort criteria for flag_evaluations-mode orgs by compiling flag-call criteria and refusing saves that still read events."},{"number":124588,"tier":"substantive","P":null,"summary":"Adds cohort-seeder support to read $feature_flag_called from flag_evaluations when a run pins it, fixing missing flag-call history for realtime cohorts."},{"number":125050,"tier":"substantive","P":null,"summary":"Saved trends insights with comparison now return resolved_compare_date_range, fixing a DST-related off-by-one in the retention notice's comparison start."},{"number":126574,"tier":"substantive","P":null,"summary":"Fixes static cohort population from HogQL queries: multi-column/aggregating queries now work, timeouts honored, and stale error messages cleared."}]},{"id":"ws3","title":"Ingestion pipeline & CDP (nodejs) · cdp","area":"Ingestion pipeline & CDP (nodejs)","agg":{"prs_n":13,"deepread_n":1,"tier_counts":{"substantive":7,"routine":1,"major":5},"points_sum":70.19,"L_mean":1,"Q_mean":1,"span_days":64,"lines":6303},"prs":[{"number":86291,"tier":"substantive","P":null,"summary":"Adds a dark-shipped ingestion producer that shadow-writes $feature_flag_called events into the flag_evaluations table for per-flag usage queries."},{"number":90579,"tier":"substantive","P":null,"summary":"CDP filter tool now renders taxonomy from source, fixing stale operators and virtual properties that silently never matched."},{"number":90615,"tier":"routine","P":2.19,"summary":"A behavior-preserving refactor that extracts the event-level `$os_name` → `$os` fill into a standalone `normalizeOsAlias` helper called before person-property lifting, with updated tests and a Rust doc-comment path fix."},{"number":98053,"tier":"substantive","P":null,"summary":"Adds a config exclusion list and kill switch so operators can hold a team back from the fleet-wide personless default for $feature_flag_called events."},{"number":113654,"tier":"substantive","P":null,"summary":"Ingestion now routes mode-2 flag calls to a new realtime-only topic so CDP destinations, workflows and plugins receive them again."},{"number":116495,"tier":"substantive","P":null,"summary":"Ingestion fork now writes person properties, created_at and mode to flag_evaluations, enabling person-based filters and lifecycle insights on flag calls."},{"number":121802,"tier":"major","P":null,"summary":"Fixes CDP hogflow matcher silently dropping events when team/hogflow lookups fail, preventing permanent event loss in the ingestion pipeline."},{"number":121819,"tier":"major","P":null,"summary":"Prevents silent event dropping in CDP consumers when internal lookups fail by forcing batch retries instead of committing offsets."},{"number":122229,"tier":"substantive","P":null,"summary":"Consolidates six duplicated CDP consumer parse loops into one shared parseBatch, fixing drift that caused dropped events."},{"number":122274,"tier":"major","P":null,"summary":"Makes Postgres replica recovery-conflict reads retriable, preventing ingestion pod crashes and dropped/dead-lettered events in core pipelines."},{"number":122365,"tier":"major","P":null,"summary":"Fixes invalid team IDs failing shared CDP team lookups, preventing pod restarts and email fail-open (suspended teams mailing, suppressed addresses receiving)."},{"number":122953,"tier":"major","P":null,"summary":"The dead-letter circuit breaker now correctly counts lookup failures, preventing silent data loss and ensuring batch failures are properly reported."},{"number":124561,"tier":"substantive","P":null,"summary":"Bumps the Node fork step's flag-evaluations TTL constant to 92 days so 90-91 day old flag calls land in flag_evaluations, unblocking a Last-90-days feature."}]},{"id":"ws4","title":"MCP server · mcp","area":"MCP server","agg":{"prs_n":11,"deepread_n":1,"tier_counts":{"substantive":8,"trivial":1,"major":1,"routine":1},"points_sum":43.49,"L_mean":2,"Q_mean":2,"span_days":80,"lines":5990},"prs":[{"number":80038,"tier":"substantive","P":null,"summary":"Sanitizes MCP forwarded header values at egress so non-Latin-1 OAuth app names no longer break every API call for affected users."},{"number":98852,"tier":"trivial","P":null,"summary":"Adds five comment lines linking the MCP flag merge helper to its backend drift-guard test; no executable change."},{"number":113494,"tier":"substantive","P":null,"summary":"MCP update-feature-flag now refuses ambiguous condition-set edits on mixed-aggregation flags, preventing stored targeting that matches nobody."},{"number":118830,"tier":"major","P":null,"summary":"Fixes a bug preventing agents from correctly saving feature flag conditions that aggregate on persons while filtering on group properties."},{"number":119876,"tier":"substantive","P":null,"summary":"MCP flag-editing tool now keeps person targeting when a condition repeats a group property, preventing silent retargeting to group bucketing."},{"number":119878,"tier":"substantive","P":null,"summary":"Fixes MCP feature-flag updates so reordering person-aggregated condition sets no longer silently swaps group types and changes who matches the flag."},{"number":120691,"tier":"substantive","P":null,"summary":"MCP feature flag tools now expose and accept condition_id, letting agents edit release conditions without silently changing flag targeting."},{"number":120777,"tier":"routine","P":null,"summary":"MCP update-feature-flag errors now name the rejected property path and key and suggest copying the stored type instead of guessing."},{"number":121501,"tier":"substantive","P":null,"summary":"MCP update-feature-flag now leaves ambiguous property types untyped instead of guessing, preventing wrong-type writes to flag filters."},{"number":121503,"tier":"substantive","P":null,"summary":"Adds condition_id-based matching to the MCP update-feature-flag merge, preventing silent targeting changes on group/mixed flags."},{"number":122896,"tier":"substantive","P":4.49,"summary":"Adds a `condition_id` to each release condition returned by the experiment MCP tools (get, get-by-flag-key, list, and the lifecycle tools) by wiring the shared `conditionIdHooks`, so agents can round-trip IDs into `update-feature-flag` and avoid mis-targeting flags when editing."}]},{"id":"ws5","title":"Product: Desktop · desktop","area":"Product: Desktop","agg":{"prs_n":7,"deepread_n":0,"tier_counts":{"routine":1,"substantive":5,"major":1},"points_sum":30,"L_mean":null,"Q_mean":null,"span_days":6,"lines":4091},"prs":[{"number":79301,"tier":"routine","P":null,"summary":"Fixes the desktop OpenAPI client generator's output path so regeneration targets the file the app actually imports."},{"number":82950,"tier":"substantive","P":null,"summary":"Desktop /clear on a finished cloud run now calls the backend clear endpoint instead of booting a sandbox, cutting cost and latency."},{"number":83471,"tier":"substantive","P":null,"summary":"Desktop skill walks now skip dot-directories via a shared predicate, fixing false over-limit errors and closing a zip path gap."},{"number":85518,"tier":"major","P":null,"summary":"Makes desktop task archiving idempotent, fixing tasks reappearing in the sidebar and preventing concurrent archives from deleting the restore checkpoint."},{"number":86464,"tier":"substantive","P":null,"summary":"Fixes desktop sessions wedging after an aborted compaction by clearing isCompacting so later messages send instead of queueing."},{"number":86703,"tier":"substantive","P":null,"summary":"Tasks created by pasting text into the composer are now named from the pasted content instead of 'Untitled', on desktop and web."},{"number":88769,"tier":"substantive","P":null,"summary":"Adds a shared swap lock to refreshSession so prompts, cancels, and /clear can't race the SDK query swap and lose prompts or corrupt sessions."}]},{"id":"ws6","title":"Django platform (misc) · api","area":"Django platform (misc)","agg":{"prs_n":7,"deepread_n":1,"tier_counts":{"substantive":5,"routine":2},"points_sum":25.92,"L_mean":2,"Q_mean":2,"span_days":29,"lines":1108},"prs":[{"number":102568,"tier":"substantive","P":null,"summary":"Adds a CI invariant test that fails when serializers leave server-owned timestamps writable, preventing a class of data-integrity bugs."},{"number":104080,"tier":"routine","P":null,"summary":"Replaces heuristic timestamp-ownership inference with an explicit reviewed list enforced by a test-only invariant guard."},{"number":110143,"tier":"substantive","P":null,"summary":"Feature flags freshness now also reads FeatureFlag.last_called_at from Postgres, so FLAG_EVALUATIONS_ONLY orgs stop showing \"No data\"."},{"number":121755,"tier":"substantive","P":5.92,"summary":"Adds the signals scout skills, replay_vision companion skill and MCP tool catalog paths to the repo_invariants CI filter in both ci-backend.yml copies, plus a test guard that fails when a citation input is not covered by the filter, so skill-only PRs can no longer skip the scout tool citation check."},{"number":121789,"tier":"substantive","P":null,"summary":"Switches structlog context_class to dict so bind() keys stay on the bound logger instead of leaking across loggers and tasks on a thread."},{"number":121791,"tier":"routine","P":null,"summary":"Makes a stable_chunks logging test order-independent by asserting only the specifier and log level, unblocking unrelated CI runs."},{"number":121809,"tier":"substantive","P":null,"summary":"Restores http_request_id tagging on ClickHouse queries from web requests, re-enabling correlation between slow/failing queries and their originating requests."}]},{"id":"ws7","title":"Product: Approvals · approvals","area":"Product: Approvals","agg":{"prs_n":5,"deepread_n":0,"tier_counts":{"substantive":4,"routine":1},"points_sum":18,"L_mean":null,"Q_mean":null,"span_days":7,"lines":517},"prs":[{"number":102404,"tier":"substantive","P":null,"summary":"Fixes gated feature flag saves failing on datetime values and makes created_at/last_called_at read-only, unblocking flag edits for teams with approval policies."},{"number":102452,"tier":"substantive","P":null,"summary":"Fixes a bug in the Approvals feature where related fields in API requests caused validation failures instead of triggering the approval workflow."},{"number":102475,"tier":"substantive","P":null,"summary":"Fixes approvals apply path failing for feature flags with encrypted payloads, so approved change requests now apply instead of erroring."},{"number":102533,"tier":"routine","P":null,"summary":"Strengthens bypass-matrix tests to send realistic editor payloads, so regression for the 500-on-save bug can't silently pass."},{"number":102563,"tier":"substantive","P":null,"summary":"Adds a Prometheus counter for failed approval ChangeRequest inserts, making a two-month silent gate failure alertable."}]},{"id":"misc","title":"杂项（含 8 条实质及以上）","area":"mixed","agg":{"prs_n":18,"deepread_n":0,"tier_counts":{"substantive":8,"routine":6,"mechanical":3,"trivial":1},"points_sum":45,"L_mean":null,"Q_mean":null,"span_days":79,"lines":11003},"prs":[{"number":76943,"tier":"substantive","P":null,"summary":"Adds an endpoint and UI to clear a finished cloud run's conversation without booting a sandbox, avoiding a costly new run."},{"number":80023,"tier":"substantive","P":null,"summary":"Adds a gated side_question command to the task-run endpoint, enabling the desktop /btw one-shot sandbox question flow."},{"number":87021,"tier":"substantive","P":null,"summary":"Closes two sandbox-escape routes in the dev sandbox by denying git config writes and pinning the wrapper's PATH."},{"number":92948,"tier":"routine","P":null,"summary":"Moves the taxonomy JSON drift check into push-time preflight and adds a --check mode, improving developer feedback for taxonomy edits."},{"number":93021,"tier":"routine","P":null,"summary":"Pins a UTC date in hogli quarantine tests so date-based fixtures don't flake across midnight rollovers."},{"number":101312,"tier":"substantive","P":null,"summary":"Keeps a task's PR visible after a resume by reading PR fields from the most recent PR-carrying run, fixing a user-visible regression."},{"number":106303,"tier":"routine","P":null,"summary":"Declares the missing @posthog/quill-charts dependency in the data_warehouse product so cold Vite dev servers resolve it."},{"number":106376,"tier":"mechanical","P":null,"summary":"Sets local dev env vars so ingestion dual-writes flag evaluations, fixing an empty local flag Usage tab."},{"number":106388,"tier":"trivial","P":null,"summary":"Pins a default mock date in ArtefactLogList stories so relative-date screenshots stop changing daily and Visual Review stops flagging unrelated PRs."},{"number":114773,"tier":"substantive","P":null,"summary":"Fixes a race where a reader's scroll during a streaming PostHog AI turn bounced back to the bottom, and stabilizes a flaky visual snapshot."},{"number":119754,"tier":"mechanical","P":null,"summary":"Refactors a brittle dashboard test by replacing large query snapshots with functional ORM row assertions."},{"number":122342,"tier":"mechanical","P":null,"summary":"Renames a CDP matcher helper from readMessage to skipIfMalformed and clarifies its comment, with no behavior change."},{"number":124461,"tier":"substantive","P":null,"summary":"Fixes experiment exposure cohorts to use the resolved exposure event, preventing empty cohorts for orgs that no longer store $feature_flag_called."},{"number":124523,"tier":"routine","P":null,"summary":"Bounds four exposure-cohort tests with a shared helper that fails fast instead of polling until CI times out."},{"number":124527,"tier":"routine","P":null,"summary":"Consolidates eight duplicated exposure-event flag stubs in experiments tests into one shared helper; test-only, no user impact."},{"number":124564,"tier":"substantive","P":null,"summary":"Paths insights now exclude $feature_flag_called events as steps, keeping results consistent before and after the flag_evaluations migration."},{"number":125253,"tier":"routine","P":null,"summary":"Adds document.body cleanup in ReportContextMenu tests to stop leftover verdict dialogs leaking between cases and unblock the frontend test gate."},{"number":125955,"tier":"substantive","P":null,"summary":"Fixes survey creation failing silently for orgs with feature-flag approval policies, adding explicit errors and approval handling across surveys, flags and approvals."}]}];
